from h import *
O=[]
O.append(R(6367232,None,
("كوكيز الكينوا ورقائق الشوكولاتة الخالية من الغلوتين","قد تتردد في تجربة كوكيز مصنوعة من الكينوا، لكن هذه الكوكيز الغنية بالألياف لذيذة وسهلة! قوامها أكثف قليلًا من الكوكيز التقليدية، لكن يمكنك تناولها دون الشعور بالذنب!","30","1 قطعة كوكيز",
["3 ملاعق كبيرة سمن نباتي (مارجرين) Smart Balance (طري)","1 ملعقة صغيرة خلاصة الفانيليا","1 بيضة كبيرة","¼ كوب مُحلٍّ قليل السعرات أو خالٍ منها","1 كوب شوفان مسطّح تقليدي (خالٍ من الغلوتين)","2 كوب كينوا مطبوخة (مبرّدة)","½ كوب خليط للخبز ((مثل Pamela’s)، خالٍ من الغلوتين)","¼ كوب رقائق شوكولاتة صغيرة"],
["سخّن الفرن مسبقًا إلى 350 درجة (175° مئوية). بطّن صينية خبز بورق الزبدة.","في وعاء كبير، اخفق السمن النباتي والفانيليا والبيض والمُحلّي قليل السعرات أو الخالي منها. امزج حتى يتجانس الخليط جيدًا.","أضف الشوفان والكينوا وخليط الخبز إلى الخليط وقلّب جيدًا. أضف رقائق الشوكولاتة بالتقليب الرفيق.","ضع الخليط بملعقة كبيرة على صينية الخبز. اخبز لمدة 15 دقيقة.","اترك الكوكيز تبرد على رف سلكي ثم احفظها في وعاء محكم الإغلاق بعد أن تبرد."],[],[])))
O.append(R(6368072,
("Galleta de mantequilla de almendra con cuatro ingredientes","Rápidas y fáciles de preparar, estas galletas de mantequilla de almendra con cuatro ingredientes son una receta para guardar entre sus favoritas la próxima vez que se le antoje algo dulce. Aptas para personas con diabetes y bajas en carbohidratos, seguro serán un postre favorito de la familia.","12","1 galleta",
["1 taza de mantequilla de almendra","1 huevo grande (ligeramente batido)","1/3 de taza de sustituto de azúcar para hornear sin azúcar","1 cucharadita de extracto de vainilla"],
["Precaliente el horno a 350 grados F. Forre una bandeja para hornear con papel pergamino.","En un tazón, combine la mantequilla de almendra, el huevo, el azúcar y el extracto de vainilla. Mezcle hasta que todos los ingredientes estén bien integrados.","Tome porciones de masa fría del tamaño de una cucharada y forme bolitas. Colóquelas en la bandeja preparada, dejando espacio entre cada una. Si la masa está demasiado blanda para formar bolitas, refrigérela 30 minutos para que se endurezca.","Con un tenedor, presione suavemente cada bolita de masa para formar un patrón entrecruzado.","Hornee en el horno precalentado durante unos 10 minutos o hasta que los bordes estén dorados.","Deje que las galletas se enfríen en la bandeja unos minutos antes de pasarlas a una rejilla para que se enfríen por completo."],[],[]),
("كوكيز زبدة اللوز بأربعة مكونات","سريعة وسهلة التحضير، كوكيز زبدة اللوز بأربعة مكونات وصفة تستحق أن تضيفها إلى مفضلاتك في المرة القادمة التي تشتهي فيها شيئًا حلوًا. مناسبة لمرضى السكري وقليلة الكربوهيدرات، وستكون بالتأكيد حلوى مفضلة لدى العائلة.","12","1 قطعة كوكيز",
["1 كوب زبدة اللوز","1 بيضة كبيرة (مخفوقة قليلًا)","⅓ كوب بديل سكر للخبز خالٍ من السكر","1 ملعقة صغيرة خلاصة الفانيليا"],
["سخّن الفرن مسبقًا إلى 350 درجة فهرنهايت (175° مئوية). بطّن صينية خبز بورق الزبدة.","في وعاء خلط، اخلط زبدة اللوز والبيض والسكر وخلاصة الفانيليا. امزج حتى تتجانس جميع المكونات جيدًا.","خذ حصصًا من العجين البارد بحجم ملعقة كبيرة وشكّلها كرات. ضع الكرات على الصينية المجهزة مع ترك مسافة بين كل كرة. إذا كان العجين طريًا جدًا بحيث يصعب تشكيله، ضعه في الثلاجة لمدة 30 دقيقة ليتماسك.","باستخدام شوكة، اضغط برفق على كل كرة عجين لتشكيل نقش متقاطع.","اخبزها في الفرن المسخّن مسبقًا لمدة 10 دقائق تقريبًا أو حتى تصبح الأطراف ذهبية اللون.","اترك الكوكيز تبرد على الصينية لبضع دقائق قبل نقلها إلى رف سلكي لتبرد تمامًا."],[],[])))
O.append(R(6368221,None,
("هليون وفلفل وفطر مقلي","الخضار غير النشوية، مثل الهليون والفلفل والفطر، غنية بالفيتامينات والمعادن، وقليلة السعرات والكربوهيدرات. استخدم أفكارًا بسيطة ولذيذة مثل هذه الوصفة لملء نصف طبقك بالخضار غير النشوية!","7","½ كوب",
["1½ ملعقة كبيرة زيت زيتون","1 رطل هليون (مقطوع الأطراف ومقطّع أثلاثًا)","½ كوب بصل أحمر (مقطّع شرائح)","8 أونصات فطر كريميني (بيبي بيلا) (مقطّع شرائح)","1 حبة فلفل رومي أحمر متوسطة (مقطّعة)","1 فص ثوم (مفروم)"],
["سخّن زيت الزيتون في مقلاة عميقة كبيرة أو ووك على نار متوسطة إلى عالية. أضف الهليون والبصل والفطر والفلفل الأحمر واطهِها لمدة 15-18 دقيقة مع التحريك المتكرر.","أضف الثوم إلى المقلاة واطهِ لمدة دقيقة واحدة. قلّب الخضار والثوم ليمتزجا."],[],[])))
O.append(R(6369435,
("Ensalada de tofu y edamame","Adéntrese en un mundo de perfección vegetal con nuestra ensalada de tofu y edamame. Tofu sedoso, edamame vibrante y una colorida variedad de verduras crujientes crean una refrescante sinfonía de sabores. Mezclada con un delicioso aderezo casero, esta ensalada lo invita a saborear lo nutritivo de cada bocado.","4","1 taza",
["14 onzas de tofu firme (firme, prensado y en cubos)","1 taza de edamame congelado (sin vaina)","1 taza de col morada (en rodajas finas)","1 taza de zanahorias (en juliana)","1/4 de taza de aceitunas verdes (en rodajas)","1 cucharada de semillas de ajonjolí","2 cucharadas de salsa de soya baja en sodio","1 cucharada de vinagre de arroz","1 cucharada de aceite de ajonjolí","1 cucharada de mantequilla de maní","1 cucharadita de miel de maple","1 cucharadita de jengibre fresco (rallado)","1 diente de ajo (picado)","1/4 de cucharadita de sal","1/4 de cucharadita de pimienta negra"],
["En un tazón grande, combine el tofu en cubos, el edamame sin vaina, la col morada en rodajas finas, la zanahoria en juliana, la cebolla de cambray en rodajas y las semillas de ajonjolí.","En un tazón pequeño, bata la salsa de soya baja en sodio, el vinagre de arroz, el aceite de ajonjolí, la mantequilla de maní, la miel de maple, el jengibre fresco rallado, el ajo picado, la sal y la pimienta negra.","Vierta el aderezo sobre la ensalada y mezcle suavemente para que quede bien cubierta."],[],[]),
("سلطة التوفو والإدامامي","ادخل عالم الكمال النباتي مع سلطة التوفو والإدامامي. التوفو الناعم والإدامامي الزاهي ومجموعة ملوّنة من الخضار المقرمشة تصنع معًا تناغمًا منعشًا من النكهات. تُقلَّب في صلصة منزلية شهية، وتدعوك هذه السلطة إلى الاستمتاع بالفائدة الصحية في كل لقمة.","4","1 كوب",
["14 أونصة توفو صلب (صلب، مضغوط ومقطّع مكعبات)","1 كوب إدامامي مجمد (مقشّر)","1 كوب ملفوف أحمر (مقطّع شرائح رفيعة)","1 كوب جزر (مقطّع شرائح طويلة رفيعة)","¼ كوب زيتون أخضر (مقطّع شرائح)","1 ملعقة كبيرة بذور السمسم","2 ملعقة كبيرة صلصة صويا قليلة الصوديوم","1 ملعقة كبيرة خل الأرز","1 ملعقة كبيرة زيت سمسم","1 ملعقة كبيرة زبدة الفول السوداني","1 ملعقة صغيرة شراب القيقب","1 ملعقة صغيرة زنجبيل طازج (مبشور)","1 فص ثوم (مفروم)","¼ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود"],
["في وعاء كبير، اخلط مكعبات التوفو والإدامامي المقشّر والملفوف الأحمر المقطّع شرائح رفيعة والجزر المقطّع شرائح طويلة والبصل الأخضر المقطّع وبذور السمسم.","في وعاء صغير، اخفق صلصة الصويا قليلة الصوديوم وخل الأرز وزيت السمسم وزبدة الفول السوداني وشراب القيقب والزنجبيل الطازج المبشور والثوم المفروم والملح والفلفل الأسود.","اسكب الصلصة على السلطة وقلّبها برفق لتتغطى بالتساوي."],[],[])))
O.append(R(6371783,
("Bowls de salmón y arroz","Estos bowls de salmón y arroz se pueden personalizar con sus verduras favoritas. La combinación de salmón, arroz y verduras frescas es una comida saludable y satisfactoria para entre semana.","4","1 filete de salmón, 1 taza de mezcla",
["16 onzas de salmón (4 filetes de 4 onzas cada uno)","2 cucharadas de salsa de soya baja en sodio","2 cucharaditas de miel","1 cucharada de aceite de ajonjolí","2 cucharaditas de jengibre fresco (picado)","2 dientes de ajo (picados)","2 tazas de arroz integral cocido","1 taza de brócoli (al vapor)","1 taza de zanahorias (ralladas)","1/4 de aguacate mediano (en rodajas)","2 tallos de cebolla de cambray (picados, para servir)"],
["En un tazón pequeño, bata la salsa de soya, la miel, el aceite de ajonjolí, el jengibre picado y el ajo picado para hacer la salsa.","Unte el salmón con parte de la salsa.","Caliente una sartén grande a fuego medio-alto y selle el salmón hasta que esté bien cocido, unos 4 minutos por lado.","Unte la parte superior del salmón con más marinada.","Arme los bowls con el arroz integral, el brócoli al vapor, el salmón y el aguacate. Rocíe con la salsa. Termine con la cebolla de cambray."],[],[]),
("أوعية السلمون والأرز","يمكن تخصيص أوعية السلمون والأرز هذه بخضارك المفضلة. يمنحك الجمع بين السلمون والأرز والخضار الطازجة وجبة صحية ومشبعة لأيام الأسبوع.","4","1 شريحة سلمون، 1 كوب من الخليط",
["16 أونصة سلمون (4 شرائح، 4 أونصات لكل شريحة)","2 ملعقة كبيرة صلصة صويا قليلة الصوديوم","2 ملعقة صغيرة عسل","1 ملعقة كبيرة زيت سمسم","2 ملعقة صغيرة زنجبيل طازج (مفروم)","2 فص ثوم (مفروم)","2 كوب أرز بني مطبوخ","1 كوب بروكلي (مطهو على البخار)","1 كوب جزر (مبشور)","¼ حبة أفوكادو متوسطة (مقطّعة شرائح)","2 عود بصل أخضر (مفروم، للتقديم)"],
["في وعاء صغير، اخفق صلصة الصويا والعسل وزيت السمسم والزنجبيل المفروم والثوم المفروم لتحضير الصلصة.","ادهن السلمون بجزء من الصلصة.","سخّن مقلاة كبيرة على نار متوسطة إلى عالية وحمّر السلمون حتى ينضج تمامًا، حوالي 4 دقائق لكل جانب.","ادهن وجه السلمون بمزيد من التتبيلة.","ركّب الأوعية بالأرز البني والبروكلي المطهو على البخار والسلمون والأفوكادو. رشّ الصلصة. وأنهِ الطبق بالبصل الأخضر."],[],[])))
O.append(R(6372211,None,
("غموس التاكو الصحي","النسخة التقليدية من غموس التاكو أعلى بكثير في الدهون وتستخدم القشدة الحامضة والجبن الكريمي. نحن نستخدم دهنًا أكثر صحة (الأفوكادو) وجبنًا قليل الدسم لنوفّر لك الكثير من السعرات الحرارية دون التخلي عن أي نكهة. هذا الغموس رائع لحفلات الشواء قبل المباريات وموسم كرة القدم!","24","1 ملعقة كبيرة مكوّمة",
["1 علبة (16 أونصة) فاصولياء مطبوخة مهروسة (خالية من الدهون)","2 ملعقة صغيرة مسحوق التشيلي","½ ملعقة صغيرة كمون","¼ ملعقة صغيرة مسحوق الثوم","1½ حبة أفوكادو متوسطة (مهروسة)","⅓ كوب سالسا","1 حبة طماطم كبيرة (منزوعة البذور ومقطّعة مكعبات)","1 كوب خس روماين (مبشور)","1 كوب خليط جبن مكسيكي مبشور"],
["في وعاء متوسط، اخلط الفاصولياء المهروسة ومسحوق التشيلي والكمون ومسحوق الثوم.","وزّع الفاصولياء المهروسة بالتساوي على طبق تقديم متوسط. وزّع الأفوكادو المهروس بالتساوي فوق الفاصولياء.","وزّع السالسا بالتساوي فوق الأفوكادو. ضع فوقها الطماطم والخس المبشور والجبن المبشور.","قدّم الغموس مع الخيار الذي تفضّله من رقائق التورتيلا المخبوزة أو رقائق الفاصولياء السوداء أو شرائح الالجيكاما. وإذا كنت تتبع نظامًا غذائيًا خاليًا من الغلوتين، فتأكد من أن رقائق التورتيلا غير متبّلة وخالية من الغلوتين."],[],[])))
O.append(R(6372891,
("Panini de pollo fácil","Un panini tostado con pan crujiente, un relleno caliente y sabroso y queso derretido es un almuerzo o una cena ligera satisfactorios y aptos para personas con diabetes. Cocine los paninis en una sartén (una de hierro fundido funciona muy bien) a fuego bajo para que el relleno se caliente por completo sin quemar el pan. Es una excelente receta para preparar con anticipación: arme todos los sándwiches de antemano y envuélvalos individualmente en papel aluminio, y luego tueste el panini justo antes de servir. Acompañe este sándwich con una ensalada sencilla, como esta ensalada de espinacas, aguacate y frutos rojos de verano, para una comida equilibrada y saludable para el corazón. Duplique: ¡cocine el doble de pollo al preparar una receta como el Pollo al estragón con hierbas y champiñones y guarde el pollo sobrante para preparar estos paninis rápidos más tarde en la semana! Esta receta es de The 12-Week Diabetes Cookbook de Linda Gassenheimer.","8","1/2 panini",
["4 cucharadas de mayonesa light","8 rebanadas (de aproximadamente 1 onza cada una) de pan integral crujiente","1/2 taza de estragón fresco","4 rebanadas (6 onzas en total) de queso suizo reducido en grasa","16 onzas de pechuga de pollo cocida (en rebanadas)","1/4 de cucharadita de sal","1/4 de cucharadita de pimienta negra","1 rociada, 0.25 gramos de aceite de oliva en aerosol"],
["Arme los sándwiches: Unte 1 cucharada de mayonesa en cada una de 4 rebanadas de pan. Cubra cada una con el estragón, el queso y el pollo, repartiendo los ingredientes de manera uniforme entre las cuatro rebanadas. Espolvoree cada una con la sal y la pimienta, y luego cubra cada sándwich con las rebanadas de pan restantes.","Rocíe con aceite de oliva en aerosol una sartén antiadherente (lo bastante grande para los paninis) y caliéntela a fuego bajo. Agregue los paninis y presione con una tapa u otra sartén limpia. Cocine 2 minutos, voltee y presione de nuevo. Cocine otros 2 minutos. (También puede usar una plancha para panini y cocinar hasta que el queso se derrita y el pan esté dorado).","Corte cada panini por la mitad y sirva cada mitad con ensalada."],[],[]),
("بانيني الدجاج السهل","بانيني محمّص بخبز مقرمش وحشوة دافئة لذيذة وجبن ذائب يجعل منه غداءً أو عشاءً خفيفًا مشبعًا ومناسبًا لمرضى السكري. اطهِ البانيني في مقلاة (المقلاة الحديدية ممتازة هنا) على نار هادئة حتى تسخن الحشوة بالكامل دون أن يحترق الخبز. وهي وصفة رائعة لتحضير الوجبات مسبقًا: جهّز جميع الساندويتشات مسبقًا ولفّ كل واحد على حدة بورق الألمنيوم، ثم حمّص البانيني قبل التقديم مباشرة. قدّم هذا الساندويتش مع سلطة جانبية بسيطة، مثل سلطة السبانخ والأفوكادو وتوت الصيف، لوجبة متوازنة صحية للقلب. ضاعف الكمية: اطهِ كمية مضاعفة من الدجاج عند تحضير وصفة مثل الدجاج بالطرخون والأعشاب مع الفطر، واحتفظ بالدجاج المتبقي لتحضير هذا البانيني السريع في وقت لاحق من الأسبوع! هذه الوصفة من كتاب The 12-Week Diabetes Cookbook للمؤلفة Linda Gassenheimer.","8","½ بانيني",
["4 ملاعق كبيرة مايونيز خفيف","8 شرائح (حوالي 1 أونصة لكل شريحة) خبز قمح كامل مقرمش","½ كوب طرخون طازج","4 شرائح (6 أونصات إجمالًا) جبن سويسري قليل الدسم","16 أونصة صدر دجاج مطبوخ (مقطّع شرائح)","¼ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود","1 بخّة، 0.25 جرام بخاخ زيت زيتون"],
["جهّز الساندويتشات: ادهن 1 ملعقة كبيرة من المايونيز على كل شريحة من 4 شرائح خبز. ضع فوق كل منها الطرخون والجبن والدجاج، مع توزيع المكونات بالتساوي على الشرائح الأربع. رشّ على كل منها الملح والفلفل، ثم غطِّ كل ساندويتش بشرائح الخبز المتبقية.","رشّ مقلاة غير لاصقة (كبيرة بما يكفي لتتسع للبانيني) ببخاخ زيت الزيتون وسخّنها على نار هادئة. ضع البانيني واضغط عليه بغطاء أو مقلاة نظيفة أخرى. اطهِه لمدة دقيقتين، ثم اقلبه واضغط مرة أخرى. اطهِه دقيقتين أخريين. (يمكنك أيضًا استخدام جهاز البانيني والطهي حتى يذوب الجبن ويصبح الخبز ذهبيًا).","اقطع كل بانيني إلى نصفين وقدّم كل نصف مع السلطة."],[],[])))
O.append(R(6373822,en=("Toasted Barley and Pepper Soup","Try other grains in this soup, such as spelt, farro, or wheat berries.","6",None,
["3 small or 2 medium carrots (peeled and diced)","1 medium onion (diced)","3/4 cup quick-cooking barley","1 tablespoon olive oil","2 roasted garlic chicken sausage links (diced)","2 stalks celery (diced)","1 medium red bell pepper (seeded and diced)","1 medium orange or yellow bell pepper (seeded and diced)","2 cloves garlic (minced)","4 cups low-sodium chicken broth","14 1/2 oz diced tomatoes (reduced sodium)","1 bay leaf","1/2 teaspoon salt (optional)","1/4 teaspoon black pepper"],
["Add the oil to a pot over medium-high heat. Add the barley and sauté until toasted, about 2 minutes. Add the sausage and sauté 2 more minutes.","Add the onion, celery, carrots, and bell peppers, and sauté for 3 minutes or until the onions begin to turn translucent.","Add the garlic and sauté 1 more minute.","Stir in the chicken broth and the tomatoes.","Add the bay leaf, salt (optional), and ground black pepper. Bring to a boil, then reduce to a simmer. Simmer, covered, for 15 minutes.","Remove the bay leaf and serve."],[],[]),
ar=("شوربة الشعير المحمّص والفلفل","جرّب حبوبًا أخرى في هذه الشوربة مثل القمح الإسباني (سبلت) أو الفارو أو حبوب القمح.","6",None,
["3 جزرات صغيرة أو 2 متوسطة (مقشّرة ومقطّعة مكعبات)","1 حبة بصل متوسطة (مقطّعة مكعبات)","¾ كوب شعير سريع الطهي","1 ملعقة كبيرة زيت زيتون","2 قطعة نقانق دجاج بالثوم المحمّص (مقطّعة مكعبات)","2 عود كرفس (مقطّع مكعبات)","1 حبة فلفل رومي أحمر متوسطة (منزوعة البذور ومقطّعة مكعبات)","1 حبة فلفل رومي برتقالي أو أصفر متوسطة (منزوعة البذور ومقطّعة مكعبات)","2 فص ثوم (مفروم)","4 أكواب مرق دجاج قليل الصوديوم","14½ أونصة طماطم مقطّعة مكعبات (مخفضة الصوديوم)","1 ورقة غار","½ ملعقة صغيرة ملح (اختياري)","¼ ملعقة صغيرة فلفل أسود"],
["أضف الزيت إلى قدر على نار متوسطة إلى عالية. أضف الشعير وقلّبه حتى يتحمّص، حوالي دقيقتين. أضف النقانق وقلّب دقيقتين أخريين.","أضف البصل والكرفس والجزر والفلفل الرومي وقلّبها لمدة 3 دقائق أو حتى يبدأ البصل في أن يصبح شفافًا.","أضف الثوم وقلّب دقيقة أخرى.","أضف مرق الدجاج والطماطم وقلّب.","أضف ورقة الغار والملح (اختياري) والفلفل الأسود المطحون. أحضرها إلى الغليان، ثم خفّف النار لتغلي على نار هادئة. اتركها على نار هادئة مغطاة لمدة 15 دقيقة.","أخرج ورقة الغار وقدّم الشوربة."],[],[])))
O.append(R(6373845,None,
("برغل ونعناع وطماطم على شرائح الخيار","هذه اللقيمات المنعشة مثالية كوجبة خفيفة بعد الظهر أو مقبلات سريعة. يمكنك تحضير خليط البرغل مسبقًا وتجميعها قبل التقديم مباشرة.","4","½ كوب من خليط البرغل و8 شرائح خيار",
["⅓ كوب برغل سريع الطهي (جاف)","1 كوب ماء","1 كوب نعناع طازج (مفروم ناعمًا)","1 حبة طماطم روما (برقوقية) متوسطة (مقطّعة مكعبات)","1 ملعقة كبيرة عصير ليمون","1½ ملعقة كبيرة زيت الكانولا","1 ملعقة كبيرة خل التفاح","¼ كوب بصل أحمر (مفروم ناعمًا)","⅛ ملعقة صغيرة رقائق الفلفل الأحمر المجروش","¼ ملعقة صغيرة ملح","32 شريحة خيار (بسمك ¼ بوصة تقريبًا لكل شريحة، 12 أونصة إجمالًا)"],
["أحضر الماء والبرغل إلى الغليان في قدر متوسطة على نار عالية. خفّف النار وغطِّ القدر واتركه على نار هادئة 12 دقيقة.","في الأثناء، اخلط بقية المكونات، عدا الخيار، في وعاء متوسط.","صفِّ البرغل في مصفاة ناعمة واشطفه بماء بارد ليبرد بسرعة. انفض السائل الزائد وقلّبه مع خليط الطماطم."],[],[])))
O.append(R(6374972,None,
("هريس القرنبيط المخبوز","لتحضير هريس القرنبيط المخبوز هذا، استخدم خلاطًا يدويًا. هذه الأداة المطبخية التي لا غنى عنها طريقة رائعة لتوفير الوقت والأواني. اهرس الطعام في الوعاء الذي طُهي فيه نفسه، ويصبح التنظيف سهلًا للغاية.","6","1 كوب",
["1 بخّة، 0.25 جم بخاخ طهي غير لاصق","2 رأس قرنبيط (مقطّع زهيرات)","¾ كوب مرق دجاج قليل الصوديوم (خالٍ من الدهون، مخفض الصوديوم)","2 ملعقة كبيرة سمن Smart Balance الأصلي بنكهة الزبدة","½ ملعقة صغيرة ملح (اختياري)","½ ملعقة صغيرة فلفل أسود","¼ كوب بقدونس طازج (مفروم، مقسّم)","3½ ملعقة كبيرة جبن بارميزان (مبشور طازجًا)"],
["سخّن الفرن مسبقًا إلى 350 درجة (175° مئوية). ادهن طبق خبز مقاس 8×8 بوصات ببخاخ الطهي.","ضع زهيرات القرنبيط ومرق الدجاج وسمن Smart Balance والملح والفلفل في قدر شوربة كبيرة على نار عالية حتى يبدأ السائل بالغليان. خفّف النار إلى غليان هادئ، وغطِّ القدر واطهِ على البخار لمدة 10-12 دقيقة أو حتى يصبح القرنبيط طريًا تمامًا عند وخزه بالشوكة.","باستخدام خلاط يدوي (غاطس) أو محضّر طعام، اخلط خليط القرنبيط حتى يصبح ناعمًا. أضف ملعقتين كبيرتين من البقدونس المفروم بالتقليب الرفيق.","في وعاء صغير، اخلط ملعقتي البقدونس الكبيرتين المتبقيتين مع الجبن المبشور.","اسكب هريس القرنبيط في طبق الخبز المجهز. رشّ الوجه بخليط الجبن والبقدونس واخبزه لمدة 5-7 دقائق أو حتى يذوب الجبن ويبدأ بالاحمرار عند الأطراف."],[],[])))
O.append(R(6375634,None,
("بارفيه الطاقة لصباح الخير","خيار فطور رائع، تميّزه القرفة والحبوب بنمط غراب-نتس في هذه الوصفة عن بارفيه الفاكهة والزبادي المعتاد.","4","1 بارفيه، حوالي 1 كوب",
["2 كوب زبادي يوناني سادة خالٍ من الدسم","1 ملعقة صغيرة قرفة مطحونة","1 حبة موز متوسطة","2½ كوب فراولة (مقطّعة شرائح)","¼ كوب حبوب إفطار بنمط غراب-نتس","2 غصن نعناع طازج (للتزيين)"],
["ضع القرفة والموز و1 كوب من الزبادي في الخلاط واخلط حتى يصبح ناعمًا. وزّعه على 4 كؤوس نبيذ أو كؤوس بارفيه.","ضع فوق كل كأس ½ كوب من شرائح الفراولة و¼ كوب من الزبادي المتبقي و1 ملعقة كبيرة من الحبوب. زيّنه بغصن نعناع إن رغبت."],[],[])))
O.append(R(6375867,
("Barras heladas de yogur griego con fresas y chocolate oscuro","Las barras heladas de yogur griego con fresas y chocolate oscuro son un delicioso postre congelado que combina la cremosidad del yogur griego con la dulzura de las fresas y el intenso chocolate oscuro.","8","2 trozos (~91 g)",
["2 tazas de yogur griego natural bajo en grasa","2 cucharadas de jarabe sin azúcar de uso múltiple","1 cucharadita de extracto de vainilla","1 taza de fresas frescas (en rodajas)","2 onzas de chispas de chocolate oscuro (sin azúcar agregada)"],
["Forre una bandeja para hornear con papel pergamino.","En un tazón, combine el yogur griego, el jarabe y el extracto de vainilla. Mezcle hasta que todo esté bien integrado.","Vierta la mezcla de yogur griego sobre la bandeja preparada y extiéndala con una espátula en una capa uniforme.","Esparza las fresas en rodajas y el chocolate oscuro picado sobre el yogur griego.","Coloque la bandeja en el congelador y deje que la barra de yogur se congele durante al menos 3 horas o hasta que esté firme.","Una vez congelada, rompa la barra en trozos. Guárdela en un recipiente hermético en el congelador."],[],[]),
("ألواح الزبادي اليوناني المجمّد بالفراولة والشوكولاتة الداكنة","ألواح الزبادي اليوناني المجمّد بالفراولة والشوكولاتة الداكنة حلوى مثلجة شهية تجمع بين كريمية الزبادي اليوناني وحلاوة الفراولة والشوكولاتة الداكنة الغنية.","8","قطعتان (حوالي 91 جم)",
["2 كوب زبادي يوناني سادة قليل الدسم","2 ملعقة كبيرة شراب خالٍ من السكر متعدد الاستخدامات","1 ملعقة صغيرة خلاصة الفانيليا","1 كوب فراولة طازجة (مقطّعة شرائح)","2 أونصة رقائق شوكولاتة داكنة (بدون سكر مضاف)"],
["بطّن صينية خبز بورق الزبدة.","في وعاء، اخلط الزبادي اليوناني والشراب وخلاصة الفانيليا. امزج حتى يتجانس الخليط جيدًا.","اسكب خليط الزبادي اليوناني على الصينية المجهزة، ووزّعه بالملعقة العريضة (السباتولا) في طبقة متساوية.","وزّع شرائح الفراولة والشوكولاتة الداكنة المفرومة فوق الزبادي اليوناني.","ضع الصينية في الفريزر واترك ألواح الزبادي تتجمد لمدة 3 ساعات على الأقل أو حتى تتماسك.","بعد أن تتجمد، اكسر الألواح إلى قطع. احفظها في وعاء محكم الإغلاق في الفريزر."],[],[])))
